import{_ as e,o as a,c as i,a2 as t}from"./chunks/framework.CWWEQfK7.js";const k=JSON.parse('{"title":"配置后端：先改哪些值","description":"从部署仓的环境变量示例开始，配置数据服务、应用密钥、浏览器访问和仓库边界。","frontmatter":{"page_id":"configuration-basic","title":"配置后端：先改哪些值","description":"从部署仓的环境变量示例开始，配置数据服务、应用密钥、浏览器访问和仓库边界。"},"headers":[],"relativePath":"configuration/basic.md","filePath":"configuration/basic.md","lastUpdated":1786627803000}'),n={name:"configuration/basic.md"};function d(l,s,p,r,h,o){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="配置后端-先改哪些值" tabindex="-1">配置后端：先改哪些值 <a class="header-anchor" href="#配置后端-先改哪些值" aria-label="Permalink to &quot;配置后端：先改哪些值&quot;">​</a></h1><p>快速部署会把后端配置放在 <code>/etc/ershu/.env</code>，API、Worker、MCP 和数据库命令都从这个目录读取它。安装脚本根据部署仓的 <code>.env.example</code> 创建文件。不要从环境变量参考表重新手写一份。</p><p>从源码运行时，仍然把 <code>.env.example</code> 复制为项目工作目录中的 <code>.env</code>。</p><p>这一页只说明第一次必须理解的值。所有字段、类型和默认值见<a href="./environment-reference">环境变量参考</a>。</p><h2 id="_1-先配置三个数据服务" tabindex="-1">1. 先配置三个数据服务 <a class="header-anchor" href="#_1-先配置三个数据服务" aria-label="Permalink to &quot;1. 先配置三个数据服务&quot;">​</a></h2><table tabindex="0"><thead><tr><th>服务</th><th>主要用途</th><th>相关设置</th></tr></thead><tbody><tr><td>PostgreSQL</td><td>账号、项目、权限、任务、文档和系统设置</td><td><code>DATABASE_URL</code> 与连接池设置</td></tr><tr><td>Redis</td><td>登录限流和计划轮询的租约协调</td><td><code>REDIS_URL</code></td></tr><tr><td>Milvus</td><td>向量索引和语义检索</td><td><code>MILVUS_URI</code>、<code>MILVUS_TOKEN</code>、<code>MILVUS_DB_NAME</code></td></tr></tbody></table><p>API、Worker 和 MCP 必须连接同一个 PostgreSQL。启用向量检索时，三者也应连接同一个 Milvus 数据库。Redis 不保存 Worker 的持久任务队列。</p><p>使用部署仓的单机 Compose 时，默认地址已经指向本机。把 <code>/etc/ershu/compose.env</code> 中的 PostgreSQL 密码同步到 <code>/etc/ershu/.env</code> 的 <code>DATABASE_URL</code>。</p><h2 id="_2-生成四项长期密钥" tabindex="-1">2. 生成四项长期密钥 <a class="header-anchor" href="#_2-生成四项长期密钥" aria-label="Permalink to &quot;2. 生成四项长期密钥&quot;">​</a></h2><p>部署包提供的脚本会生成 PostgreSQL 与 MinIO 密码、<code>DATABASE_URL</code> 和四项长期密钥：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --directory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/ershu/current</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-sync</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  scripts/generate_config_values.py</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>把 <code>SECRET_KEY</code>、<code>ENCRYPTION_KEY</code> 和 <code>MCP_KEY_PEPPER</code> 填入 <code>/etc/ershu/.env</code>：</p><ul><li><code>SECRET_KEY</code>：保护登录令牌和 CSRF 令牌；</li><li><code>ENCRYPTION_KEY</code>：加密保存仓库凭据和模型密钥；</li><li><code>MCP_KEY_PEPPER</code>：保护 MCP 密钥摘要。</li></ul><p>三个值都不能少于 32 个字符，不能相同，也不能保留 <code>replace-me</code> 一类占位值。更换它们会让现有会话、密文或 MCP 密钥失效，因此生产环境应放进密钥管理系统并长期保存。</p><p>同一条命令输出的 <code>OPAQUE_SERVER_SETUP</code> 也要写入该文件。更换后，已有密码记录不能继续使用。生产环境必须明确设置；开发环境可以自动生成并保存，但第一次部署就应固定。</p><h2 id="_3-配好浏览器与反向代理" tabindex="-1">3. 配好浏览器与反向代理 <a class="header-anchor" href="#_3-配好浏览器与反向代理" aria-label="Permalink to &quot;3. 配好浏览器与反向代理&quot;">​</a></h2><p>本地开发可以保留：</p><div class="language-dotenv vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HOST</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">127.0.0.1</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">PORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">8000</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">CORS_ORIGINS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://localhost:3000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SECURE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">false</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">SESSION_COOKIE_SAMESITE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lax</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>生产环境需要改为：</p><ul><li><code>ENVIRONMENT=production</code>；</li><li><code>SESSION_COOKIE_SECURE=true</code>；</li><li><code>CORS_ORIGINS</code> 只包含实际前端的 HTTPS 来源；</li><li>经过反向代理时开启 <code>PROXY_HEADERS</code>，并让 <code>FORWARDED_ALLOW_IPS</code> 只信任真实代理地址；</li><li>API 和 MCP 继续监听内网或回环地址，只由 HTTPS 代理对外开放。</li></ul><p>浏览器与 API 使用同一个域名最容易配置。跨域部署还要同时处理 CORS、Cookie、来源检查和代理协议，不要只改前端地址。</p><h2 id="_4-限制仓库从哪里来" tabindex="-1">4. 限制仓库从哪里来 <a class="header-anchor" href="#_4-限制仓库从哪里来" aria-label="Permalink to &quot;4. 限制仓库从哪里来&quot;">​</a></h2><table tabindex="0"><thead><tr><th>设置</th><th>建议</th></tr></thead><tbody><tr><td><code>REPOSITORY_STORAGE_PATH</code></td><td>使用明确、可写、可持久保存的目录</td></tr><tr><td><code>GIT_ALLOWED_HOSTS</code></td><td>只列出团队实际使用的 Git 主机</td></tr><tr><td><code>ALLOW_INSECURE_GIT_URLS</code></td><td>保持 <code>false</code></td></tr><tr><td><code>ALLOW_FILE_GIT_URLS</code></td><td>保持 <code>false</code>，除非已经评估本地文件协议风险</td></tr><tr><td><code>TRUSTED_LOCAL_PATHS</code></td><td>只列出允许 Ershu 读取的本地仓库根目录</td></tr><tr><td><code>ALLOW_DEV_OPEN_LOCAL_REPOSITORY_PATHS</code></td><td>生产环境保持 <code>false</code></td></tr></tbody></table><p>浏览器所在机器能看到的本地路径，不一定能被 Worker 或 MCP 所在主机读取。登记本地仓库前，先确认实际进程能访问同一路径。</p><p>GitHub 或 GitLab Token 可以作为后备凭据，但更推荐在网页凭据库中按仓库分配 Token 或 SSH 密钥。不要把真实凭据提交到 <code>.env.example</code>。</p><h2 id="_5-模型通道不写进-env" tabindex="-1">5. 模型通道不写进 <code>.env</code> <a class="header-anchor" href="#_5-模型通道不写进-env" aria-label="Permalink to &quot;5. 模型通道不写进 \`.env\`&quot;">​</a></h2><p>语言模型、向量模型和重排模型都在管理后台创建。模型名称、API Key、服务地址和计费设置保存在数据库中，敏感值由 <code>ENCRYPTION_KEY</code> 加密。</p><p>生成 Wiki 至少需要一个可用的语言模型通道。语义搜索还需要单独的向量模型通道。没有向量模型时，关键词搜索仍可工作。</p><h2 id="_6-启动后怎样确认" tabindex="-1">6. 启动后怎样确认 <a class="header-anchor" href="#_6-启动后怎样确认" aria-label="Permalink to &quot;6. 启动后怎样确认&quot;">​</a></h2><p>快速部署使用 systemd 完成数据库升级并启动后端：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu-migrate.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ershu.target</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>然后检查：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="复制代码 / Copy code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8000/api/v1/health/dependencies</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>第一个地址只说明 API 进程能响应。第二个地址检查 PostgreSQL 和 Milvus，但不检查 Redis、Worker 或模型通道。完整部署还要确认 Worker 能领取一条真实任务，并实际完成一次登录和模型通道测试。</p><p>从源码运行时，请按<a href="/development/local-setup">本地开发环境</a>中的 UV 命令启动各组件。</p><p>不知道哪个值覆盖了哪个值时，看<a href="./loading-and-overrides">配置加载与覆盖</a>。准备上线时，再按<a href="./security">权限与安全</a>逐项核对。</p>`,36)])])}const E=e(n,[["render",d]]);export{k as __pageData,E as default};
